package br.com.equilibra.cashflow.application;
import br.com.equilibra.account.application.AccountBalanceQueryService; import br.com.equilibra.cashflow.api.CashFlowDtos; import br.com.equilibra.commitment.domain.*; import br.com.equilibra.commitment.infrastructure.FinancialCommitmentRepository; import br.com.equilibra.shared.api.CurrentUser; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service public class CashFlowProjectionService { private final FinancialCommitmentRepository commitments; private final AccountBalanceQueryService balances; private final CurrentUser current; public CashFlowProjectionService(FinancialCommitmentRepository c,AccountBalanceQueryService b,CurrentUser u){commitments=c;balances=b;current=u;}
 @Transactional(readOnly=true) public CashFlowDtos.Response project(LocalDate from,LocalDate to,List<String> accountIds){if(from==null||to==null||to.isBefore(from)||to.isAfter(from.plusMonths(12)))throw new IllegalArgumentException("Projection interval must be between 0 and 12 months.");var selected=accountIds==null?balances.list(false):balances.list(false).stream().filter(x->accountIds.contains(x.id())).toList();BigDecimal opening=selected.stream().map(x->x.currentBalance()).reduce(BigDecimal.ZERO,BigDecimal::add);var events=accountIds==null?commitments.pendingBetween(current.id().toString(),from,to):commitments.pendingBetweenAccounts(current.id().toString(),from,to,accountIds);var points=new ArrayList<CashFlowDtos.Point>();var eventDtos=new ArrayList<CashFlowDtos.Event>();BigDecimal income=BigDecimal.ZERO,expense=BigDecimal.ZERO,balance=opening;for(LocalDate d=from;!d.isAfter(to);d=d.plusDays(1)){for(var e:events)if(e.getDueDate().equals(d)){if(e.getType()==CommitmentType.INCOME){balance=balance.add(e.getPlannedAmount());income=income.add(e.getPlannedAmount());}else{balance=balance.subtract(e.getPlannedAmount());expense=expense.add(e.getPlannedAmount());}eventDtos.add(new CashFlowDtos.Event(e.getId(),e.getDueDate(),e.getDescription(),e.getType().name(),e.getPlannedAmount(),e.getAccountId(),e.getCategoryId()));}points.add(new CashFlowDtos.Point(d,balance));}return new CashFlowDtos.Response(from,to,opening,income,expense,income.subtract(expense),balance,points.stream().map(CashFlowDtos.Point::balance).min(Comparator.naturalOrder()).orElse(opening),points,eventDtos);}}
